export function getSql(tblName, tblData, alternateName) {
  tblData = tblData || getSqlTable();
  const altName = alternateName || tblName;
  let sql;
  if (tblName.substr(0, 4) == "idx_") {
    // If this is an index, we need construct the SQL differently
    const idxTbl = tblData[tblName].shift();
    const idxOn = idxTbl + "(" + tblData[tblName].join(",") + ")";
    sql = `CREATE INDEX ${altName} ON ${idxOn};`;
  } else {
    sql = `CREATE TABLE ${altName} (`;
    for (const [key, type] of Object.entries(tblData[tblName])) {
      sql += `\n    ${key} ${type},`;
    }
  }

  return sql.replace(/,\s*$/, "\n);");
}

/**
 * Gets all SQL for the given table data
 *
 * @param {string} version - The database schema version to retrieve. If null,
 *   the latest schema version will be used.
 * @returns {string} The SQL Statement for the given version as a string.
 */
export function getAllSql(version) {
  const tblData = getSqlTable(version);
  let sql = "";
  for (const tblName in tblData) {
    sql += getSql(tblName, tblData) + "\n\n";
  }
  lazy.log.debug("Storage: Full SQL statement is " + sql);
  return sql;
}
